"use strict";
/* exercises.js — content only: concept text, the EX exercise definitions and the COURSES outline. No DOM.
   Classic script (not a module): its top-level const/let/function names are shared with the other app scripts. Load order is set in index.html. */
/* ================= EXERCISES & COURSES ================= */
/* Shared concept text — variants of the same formula reuse this so the concept panel stays consistent across a deep practice pack. */
const SUM_CONCEPT = "<p><b class='term'>SUM</b> adds every number in its arguments. Arguments can be single cells, ranges, or a mix.</p><span class='formula'>=SUM(range)<br>=SUM(A1, A3, B1:B5)</span><p>Text and blank cells inside a range are ignored.</p>";
const AVERAGE_CONCEPT = "<p><b class='term'>AVERAGE</b> returns the arithmetic mean of the numeric values in its arguments — the sum divided by the count of numbers.</p><span class='formula'>=AVERAGE(range)</span><p>Blank and text cells are excluded from both the sum and the count. In finance this is the workhorse for peer-group averages (comps), consensus estimates, historical baselines, and moving averages.</p>";
const MINMAX_CONCEPT = "<p><b class='term'>MAX</b> and <b class='term'>MIN</b> return the largest and smallest numbers in a range — used individually to identify highs and lows, or subtracted to compute a spread.</p><span class='formula'>=MAX(range)<br>=MIN(range)<br>=MAX(range)-MIN(range)</span><p>Finance uses: 52-week highs / lows, best or worst quarter, yield-spread ranges, sector-return dispersion, bull-case and bear-case broker targets.</p>";
const VLOOKUP_CONCEPT = "<p><b class='term'>VLOOKUP</b> searches for a value in the <b>first column</b> of a table and returns a value from a specified column in the same row.</p><span class='formula'>=VLOOKUP(lookup_value, table_array, col_index, [range_lookup])</span><p><code>FALSE</code> = exact match (use this almost always). <code>TRUE</code> or omitted = approximate match (requires sorted first column). Finance uses: pull CMP, P/E, market cap, or any metric from a master ticker list.</p>";
const XLOOKUP_CONCEPT = "<p><b class='term'>XLOOKUP</b> is the modern replacement for VLOOKUP. It uses separate lookup and return ranges (no column counting), defaults to exact match, and has a built-in not-found fallback.</p><span class='formula'>=XLOOKUP(lookup_value, lookup_array, return_array, [if_not_found], [match_mode], [search_mode])</span><p>Finance uses: any lookup where VLOOKUP works, plus left-side lookups, last-match searches, and clean error handling without wrapping in IFERROR.</p>";
const INDEXMATCH_CONCEPT = "<p><b class='term'>MATCH</b> returns the position of a value in a range. <b class='term'>INDEX</b> returns the value at a given position in a range. Combined, they form the most flexible lookup in Excel — no left-column restriction, works in any direction.</p><span class='formula'>=INDEX(return_range, MATCH(lookup_value, lookup_range, 0))</span><p><code>0</code> in MATCH = exact match. Finance uses: two-way lookups in comps tables, pulling data from any column, cross-referencing multiple datasets.</p>";
const IFERROR_CONCEPT = "<p><b class='term'>IFERROR</b> catches any error (#N/A, #DIV/0!, #VALUE!, #REF!) and returns a fallback value instead. It wraps around another formula.</p><span class='formula'>=IFERROR(formula, value_if_error)</span><p>Finance uses: wrap every VLOOKUP/INDEX+MATCH so missing tickers show 'N/A' instead of ugly #N/A errors. Wrap divisions so zero-revenue quarters don't blow up margin calculations.</p>";
const COUNTIFS_CONCEPT = "<p><b class='term'>COUNTIFS</b> counts cells that meet <b>multiple criteria</b> simultaneously. Each pair of arguments is a (range, criterion).</p><span class='formula'>=COUNTIFS(range1, criteria1, range2, criteria2, ...)</span><p>All ranges must be the same size. A cell is counted only if it passes every criterion. Finance uses: count stocks by sector + rating, filter portfolio by multiple screens, count trades above threshold in a date range.</p>";
const AVERAGEIFS_CONCEPT = "<p><b class='term'>AVERAGEIFS</b> averages cells that meet <b>multiple criteria</b>. Like SUMIFS, the average range comes first.</p><span class='formula'>=AVERAGEIFS(average_range, criteria_range1, criteria1, criteria_range2, criteria2, ...)</span><p>Finance uses: average P/E by sector, average return above a threshold, average salary by department and grade, sector-specific yield calculations.</p>";
const TRIM_CONCEPT = "<p><b class='term'>TRIM</b> removes extra spaces from text — leading, trailing, and double spaces between words collapse to single spaces.</p><span class='formula'>=TRIM(text)</span><p>Finance use: data pasted from Bloomberg, Capital IQ, or PDFs often has invisible spaces that break VLOOKUPs. TRIM is the first fix.</p>";
const LEFTRIGHT_CONCEPT = "<p><b class='term'>LEFT</b> extracts the first N characters. <b class='term'>RIGHT</b> extracts the last N. <b class='term'>MID</b> extracts from any position.</p><span class='formula'>=LEFT(text, num_chars)<br>=RIGHT(text, num_chars)<br>=MID(text, start_pos, num_chars)</span><p>Finance use: parse ISINs, split exchange:ticker codes, extract year from period labels, pull account codes from GL strings.</p>";
const LEN_CONCEPT = "<p><b class='term'>LEN</b> returns the number of characters in a text string, including spaces.</p><span class='formula'>=LEN(text)</span><p>Finance use: validate ISIN length (must be 12), detect hidden trailing spaces that break lookups, check PAN/GSTIN format.</p>";
const FIND_CONCEPT = "<p><b class='term'>FIND</b> returns the position of one text string inside another (case-sensitive). Returns #VALUE! if not found.</p><span class='formula'>=FIND(find_text, within_text, [start_num])</span><p>Finance use: locate delimiters in raw data to split fields — the colon in 'NSE:RELIANCE', the hyphen in account codes, the space in 'First Last'.</p>";
const SUBSTITUTE_CONCEPT = "<p><b class='term'>SUBSTITUTE</b> replaces all occurrences of one text string with another inside a cell.</p><span class='formula'>=SUBSTITUTE(text, old_text, new_text)</span><p>Finance use: remove commas from Indian number format ('1,25,000' → '125000'), strip currency symbols from pasted data, clean Bloomberg ticker suffixes (.NS, .BO).</p>";
const ABS_CONCEPT = "<p><b class='term'>ABS</b> returns the absolute (positive) value of a number, stripping the sign.</p><span class='formula'>=ABS(number)</span><p>Finance use: budget variance analysis (actual vs budget — you want the SIZE of the miss, not the direction), tracking deviation from targets, computing absolute returns regardless of direction.</p>";
const AND_CONCEPT = "<p><b class='term'>AND</b> returns TRUE only if ALL conditions are TRUE. <b class='term'>OR</b> returns TRUE if ANY condition is TRUE. Typically used inside IF to test multiple criteria.</p><span class='formula'>=AND(condition1, condition2, ...)<br>=OR(condition1, condition2, ...)<br>=IF(AND(B2>0, C2>15), \"Pass\", \"Fail\")</span><p>Finance use: multi-criteria screening (PE < 20 AND ROE > 15), eligibility checks (revenue > threshold AND years > 3), alert flags (margin dropped OR growth negative).</p>";
const HLOOKUP_CONCEPT = "<p><b class='term'>HLOOKUP</b> searches for a value in the first <b>row</b> of a table and returns a value from a specified row below it. Like VLOOKUP rotated 90°.</p><span class='formula'>=HLOOKUP(lookup_value, table_array, row_index, [range_lookup])</span><p>Finance use: comps tables laid out horizontally (companies across columns, metrics down rows), quarterly data in wide format, cross-tab lookups.</p>";
const IF_CONCEPT = "<p><b class='term'>IF</b> tests a condition and returns one of two values.</p><span class='formula'>=IF(test, value_if_true, value_if_false)</span><p>Text results must be in double quotes. Comparison operators: <code>= &lt;&gt; &lt; &gt; &lt;= &gt;=</code>.</p><p>Finance use: classify transactions (profit/loss), assign ratings (buy/sell), flag exceptions (over budget / within budget), apply conditional pricing.</p>";
const NESTEDIF_CONCEPT = "<p>An <b class='term'>IF</b> can contain another IF in its false branch, creating tiers. Test from strictest to loosest.</p><span class='formula'>=IF(t1,\"A\",IF(t2,\"B\",\"C\"))</span><p>Finance use: credit rating tiers, tax bracket assignment, commission slabs, risk categorization (Low/Medium/High).</p>";
const COUNTIF_CONCEPT = "<p><b class='term'>COUNTIF</b> counts cells in a range that satisfy a criterion.</p><span class='formula'>=COUNTIF(range, criteria)</span><p>Criteria with operators are quoted strings: <code>\">=50\"</code>, <code>\"&lt;&gt;Buy\"</code>. A bare value matches equality.</p><p>Finance use: count Buy ratings, count quarters with positive growth, tally stocks above a P/E threshold.</p>";
const SUMIF_CONCEPT = "<p><b class='term'>SUMIF</b> sums values where a parallel range meets a criterion.</p><span class='formula'>=SUMIF(criteria_range, criteria, sum_range)</span><p>The first range is tested; the third is summed. They must be the same size.</p><p>Finance use: sum revenue by region, total expenses by category, aggregate AUM by fund type.</p>";
const ROUND_CONCEPT = "<p><b class='term'>ROUND</b> rounds a number to a set number of decimal places.</p><span class='formula'>=ROUND(number, digits)</span><p>Finance use: round EPS to 2 decimals, margin % to 1 decimal, per-unit cost to nearest rupee, interest calculations to 2 places.</p>";
const CONCAT_CONCEPT = "<p>The <b class='term'>&amp;</b> operator joins text values. Literal text — including a single space — goes in double quotes.</p><span class='formula'>=A2&\" \"&B2</span><p>Finance use: build composite keys for lookups (Ticker&Year), create labels for charts, assemble report headers.</p>";
const COUNT_CONCEPT = "<p><b class='term'>COUNT</b> counts only numeric cells. <b class='term'>COUNTA</b> counts every non-empty cell, including text.</p><span class='formula'>=COUNT(range)  → numbers only<br>=COUNTA(range) → anything non-empty</span><p>Finance use: count how many quarters have reported (not 'pending'), how many prices are available vs 'N/A', data completeness checks.</p>";
const POWER_CONCEPT = "<p><b class='term'>POWER</b> raises a number to a given exponent.</p><span class='formula'>=POWER(base, exponent)</span><p>Finance use: CAGR = (End/Start)^(1/n) − 1. Also: compound interest (Principal × (1+r)^n), geometric mean returns, future value calculations. POWER(x, 0.5) = square root.</p>";
const ROUNDUP_CONCEPT = "<p><b class='term'>ROUNDUP</b> always rounds away from zero (makes the number larger in absolute terms).</p><span class='formula'>=ROUNDUP(number, digits)</span><p>Finance use: EMI calculations (bank charges full rupees), provision amounts (always round up for conservatism), tax liabilities (round up to be safe), ceiling estimates in budgets.</p>";
const ROUNDDOWN_CONCEPT = "<p><b class='term'>ROUNDDOWN</b> always rounds toward zero (truncates, makes the number smaller in absolute terms).</p><span class='formula'>=ROUNDDOWN(number, digits)</span><p>Finance use: NAV calculations (AMC convention rounds down), bonus/split share allocation (can't issue fractional shares), conservative revenue estimates, floor values.</p>";
const UPPER_CONCEPT = "<p><b class='term'>UPPER</b> converts all text to UPPERCASE.</p><span class='formula'>=UPPER(text)</span><p>Finance use: standardize ticker symbols, format regulatory filings (BSE/SEBI require uppercase), normalize data before VLOOKUP (case mismatch causes #N/A).</p>";
const LOWER_CONCEPT = "<p><b class='term'>LOWER</b> converts all text to lowercase.</p><span class='formula'>=LOWER(text)</span><p>Finance use: generate email addresses from employee names, create system usernames, normalize text for comparison where case shouldn't matter.</p>";
const PROPER_CONCEPT = "<p><b class='term'>PROPER</b> capitalizes the first letter of each word, lowercases the rest.</p><span class='formula'>=PROPER(text)</span><p>Finance use: clean client names from ALL-CAPS KYC forms, format company names for presentation, fix inconsistent capitalization in imported data.</p>";
const TEXTJOIN_CONCEPT = "<p><b class='term'>TEXTJOIN</b> joins text from multiple cells with a delimiter between them. The second argument (ignore_empty) skips blank cells when TRUE.</p><span class='formula'>=TEXTJOIN(delimiter, ignore_empty, text1, [text2], ...)</span><p>Finance use: build comma-separated watchlists, create compound descriptions, assemble multi-part reference codes. More powerful than & for joining many cells.</p>";
const TODAY_CONCEPT = "<p><b class='term'>TODAY()</b> returns today's date as a serial number. It takes no arguments and updates every time the sheet recalculates.</p><span class='formula'>=TODAY()</span><p>Finance use: days to maturity, bond holding period, receivable aging, option expiry countdown. Often used with DAYS or simple subtraction.</p>";
const YEARMONTHDAY_CONCEPT = "<p><b class='term'>YEAR</b>, <b class='term'>MONTH</b>, and <b class='term'>DAY</b> extract components from a date.</p><span class='formula'>=YEAR(date)  → 2024<br>=MONTH(date) → 8<br>=DAY(date)   → 15</span><p>Finance use: group transactions by fiscal year, compute quarters from months, extract payment due dates, identify financial year (April–March for India).</p>";
const DAYS_CONCEPT = "<p><b class='term'>DAYS</b> returns the number of days between two dates.</p><span class='formula'>=DAYS(end_date, start_date)</span><p>Note: end date comes FIRST. Finance use: settlement periods, receivable aging, holding period for STCG/LTCG classification, interest accrual days.</p>";
const DATE_CONCEPT = "<p><b class='term'>DATE</b> constructs a date from year, month, and day components.</p><span class='formula'>=DATE(year, month, day)</span><p>Finance use: build maturity dates from issue date + tenure, construct fiscal year start/end dates, create first-of-month dates for timelines. DATE handles overflow: DATE(2024,13,1) → Jan 1, 2025.</p>";
const TEXT_CONCEPT = "<p><b class='term'>TEXT</b> converts a number or date to text using a format code.</p><span class='formula'>=TEXT(value, format_text)</span><p>Common codes: <code>\"MMM-YYYY\"</code> → Aug-2024, <code>\"DD-MMM-YY\"</code> → 15-Aug-24, <code>\"#,##0\"</code> → 1,25,000, <code>\"0.00%\"</code> → 12.50%.</p><p>Finance use: format dates for report headers, create period labels, display numbers as text for concatenation.</p>";
const MOD_CONCEPT = "<p><b class='term'>MOD</b> returns the remainder after division.</p><span class='formula'>=MOD(number, divisor)</span><p>Finance use: identify quarter-end months (MOD(month,3)=0), check if a year is a leap year, alternate row highlighting, EMI installment number tracking.</p>";
const INT_CONCEPT = "<p><b class='term'>INT</b> rounds DOWN to the nearest integer (toward negative infinity).</p><span class='formula'>=INT(number)</span><p>Finance use: compute whole lot sizes (can't buy 2.7 lots), extract completed years from months, truncate to whole shares for order placement, floor calculations.</p>";
const SQRT_CONCEPT = "<p><b class='term'>SQRT</b> returns the square root of a number.</p><span class='formula'>=SQRT(number)</span><p>Finance use: annualizing daily volatility (daily σ × √252), computing standard deviation components, distance metrics in quantitative screens.</p>";
const PRODUCT_CONCEPT = "<p><b class='term'>PRODUCT</b> multiplies all numbers in its arguments. Ignores text and blanks.</p><span class='formula'>=PRODUCT(number1, [number2], ...)</span><p>Finance use: chain compounding factors ((1+r1)×(1+r2)×...), multiply discount factors along a yield curve, compute cumulative probability, geometric linking of returns.</p>";
const MEDIAN_CONCEPT = "<p><b class='term'>MEDIAN</b> returns the middle value of a set of numbers. If the count is even, it averages the two middle values.</p><span class='formula'>=MEDIAN(number1, [number2], ...)</span><p>Finance use: median P/E for a peer group (less distorted by outliers than average), median salary for comp analysis, median deal size for investment banking league tables.</p>";
const AVERAGEIF_CONCEPT = "<p><b class='term'>AVERAGEIF</b> averages cells that meet a single criterion.</p><span class='formula'>=AVERAGEIF(criteria_range, criteria, [average_range])</span><p>Finance use: average P/E for a specific sector, average salary by department, mean return for a particular rating category.</p>";
const NOT_CONCEPT = "<p><b class='term'>NOT</b> reverses a logical value: TRUE becomes FALSE, FALSE becomes TRUE.</p><span class='formula'>=NOT(logical)</span><p>Finance use: invert screening conditions, flip eligibility flags, exclude specific categories. Often combined with IF, AND, OR.</p>";
const ISNUMBER_CONCEPT = "<p><b class='term'>ISNUMBER</b> returns TRUE if the cell contains a number. <b class='term'>ISBLANK</b> returns TRUE if the cell is empty.</p><span class='formula'>=ISNUMBER(value)  =ISBLANK(value)</span><p>Finance use: validate data imports, check for missing mandatory data, build data quality dashboards, audit spreadsheets before model submission.</p>";
const COUNTBLANK_CONCEPT = "<p><b class='term'>COUNTBLANK</b> counts empty cells in a range.</p><span class='formula'>=COUNTBLANK(range)</span><p>Finance use: data completeness audits, coverage gap analysis, identify holes in a dataset before running models, compliance checks for mandatory fields.</p>";

